package com.evfleet.backend.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
import jakarta.validation.constraints.*;
@Entity @Table(name="vehicles",indexes=@Index(name="idx_vehicles_owner",columnList="owner_user_id"))
public class Vehicle {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="owner_user_id",nullable=false) private Long ownerUserId; @NotBlank @Size(max=20) @Column(nullable=false,length=20) private String vehicleType; @Size(max=80) @Column(length=80) private String brand; @NotBlank @Size(max=80) @Column(nullable=false,length=80) private String model; @Size(max=30) @Column(length=30) private String registrationNumber; @Positive @Column(precision=7,scale=2) private BigDecimal batteryCapacityKwh; @Size(max=40) @Column(length=40) private String connectorType; private Instant createdAt=Instant.now();
 public Vehicle(){} public Long getId(){return id;} public Long getOwnerUserId(){return ownerUserId;} public void setOwnerUserId(Long v){ownerUserId=v;} public String getVehicleType(){return vehicleType;} public void setVehicleType(String v){vehicleType=v;} public String getBrand(){return brand;} public void setBrand(String v){brand=v;} public String getModel(){return model;} public void setModel(String v){model=v;} public String getRegistrationNumber(){return registrationNumber;} public void setRegistrationNumber(String v){registrationNumber=v;} public BigDecimal getBatteryCapacityKwh(){return batteryCapacityKwh;} public void setBatteryCapacityKwh(BigDecimal v){batteryCapacityKwh=v;} public String getConnectorType(){return connectorType;} public void setConnectorType(String v){connectorType=v;}
}
